const fs = require('fs');
const path = require('path');

const SNAPSHOT_DIR = path.join(__dirname, 'snapshot');
const OUTPUT_FILE = path.join(__dirname, 'snapshot-list.js');

// 读取 snapshot 目录下所有 .webp 文件，按文件名排序
const files = fs.readdirSync(SNAPSHOT_DIR)
  .filter(file => file.toLowerCase().endsWith('.webp'))
  .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));

// 生成 JS 内容
const jsContent = `// Auto-generated by generate-snapshot-list.js
// Do not edit manually
const SNAPSHOT_FILES = ${JSON.stringify(files, null, 2)};
`;

fs.writeFileSync(OUTPUT_FILE, jsContent, 'utf-8');
console.log(`✅ Generated snapshot-list.js with ${files.length} files.`);
